CREATE TABLE IF NOT EXISTS sms_messages(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,event VARCHAR(40) NOT NULL,mobile VARCHAR(11) NOT NULL,template VARCHAR(100) NOT NULL DEFAULT '',tokens TEXT NULL,status VARCHAR(20) NOT NULL DEFAULT 'queued',attempts TINYINT UNSIGNED NOT NULL DEFAULT 0,next_attempt_at DATETIME NULL,provider_id VARCHAR(40) NULL,provider_status SMALLINT NULL,cost INT UNSIGNED NULL,error VARCHAR(255) NULL,dedupe_key VARCHAR(120) NULL,booking_id BIGINT UNSIGNED NULL,user_id BIGINT UNSIGNED NULL,created_by_admin BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,sent_at DATETIME NULL,UNIQUE KEY sms_dedupe(dedupe_key),INDEX sms_queue(status,next_attempt_at),INDEX sms_mobile(mobile,created_at),INDEX sms_event(event,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS sms_templates(event VARCHAR(40) PRIMARY KEY,template VARCHAR(100) NOT NULL DEFAULT '',enabled TINYINT NOT NULL DEFAULT 0,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cron_runs(task VARCHAR(60) PRIMARY KEY,last_started_at DATETIME NULL,last_finished_at DATETIME NULL,last_status VARCHAR(20) NOT NULL DEFAULT 'never',last_message VARCHAR(500) NOT NULL DEFAULT '',runs INT UNSIGNED NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4
